def largest_run_sum(nums: list[int]) -> int:
    best, current = nums[0], 0           # current: best total of a run ending at the value just read
    for x in nums:
        current = max(current, 0) + x    # a negative carried total only lowers x: start over at x
        best = max(best, current)
    return best
